-- Aprenda se Divertindo · 118 · Trilha Policial · troca de 100 questões fáceis
-- Rode depois do 117-mercadopago-pix-automatico.sql. Cole tudo no SQL Editor e clique em Run. Rodar de novo não causa problema.
-- Substitui 100 questões fáceis (nível 0) que eram quase iguais a outras do banco por 100 novas, nos mesmos números.
-- Matérias: Legislação Especial 32, Direitos Humanos 28, Processo Penal 25, Direito Penal 9, Medicina Legal 6.

insert into public.questoes (id, materia, nivel, enunciado, opcoes, explicacao)
select id, materia, nivel, enunciado, opcoes, explicacao
from jsonb_to_recordset($q$[{"id": 2020, "materia": "ppen", "nivel": 0, "enunciado": "O inquérito policial nos crimes de ação pública pode começar, entre outras formas, por:", "opcoes": ["Portaria do delegado ou requisição do MP", "Ordem do governador do estado ou do secretário", "Pedido da imprensa local", "Decisão do prefeito"], "explicacao": "Art. 5º, I e II, do CPP."}, {"id": 2030, "materia": "dh", "nivel": 0, "enunciado": "Os direitos humanos pertencem a todas as pessoas pelo simples fato de:", "opcoes": ["Serem humanas", "Serem brasileiras", "Votarem", "Pagarem impostos"], "explicacao": "Eles decorrem da dignidade da pessoa humana."}, {"id": 2031, "materia": "dh", "nivel": 0, "enunciado": "A Declaração Universal dos Direitos Humanos, de 1948, completou 75 anos em:", "opcoes": ["2023", "2018", "2020", "2025"], "explicacao": "1948 + 75 = 2023."}, {"id": 2043, "materia": "ppen", "nivel": 0, "enunciado": "Nos crimes de ação penal privada, o inquérito só pode ser aberto com:", "opcoes": ["Requerimento de quem pode oferecer a queixa", "Ordem do delegado, por conta própria e sem pedido algum", "Denúncia anônima feita por telefone", "Pedido de qualquer vizinho"], "explicacao": "Art. 5º, § 5º, do CPP."}, {"id": 2053, "materia": "dh", "nivel": 0, "enunciado": "Ninguém pode vender ou transferir seus direitos humanos. Essa característica é a:", "opcoes": ["Inalienabilidade", "Prescritibilidade", "Temporariedade", "Territorialidade"], "explicacao": "Direitos humanos são inalienáveis."}, {"id": 2071, "materia": "ppen", "nivel": 0, "enunciado": "Antes de abrir inquérito a partir de uma denúncia anônima, a polícia faz diligências para conferir os fatos, chamadas de:", "opcoes": ["Verificação de procedência das informações", "Acareação", "Pronúncia", "Intimação por edital de todos os investigados"], "explicacao": "Art. 5º, § 3º, do CPP: a autoridade verifica a procedência das informações."}, {"id": 2074, "materia": "ppen", "nivel": 0, "enunciado": "Concluído o inquérito, o delegado envia os autos com o relatório:", "opcoes": ["Ao juiz competente", "À imprensa local", "Ao prefeito da cidade", "Diretamente ao réu"], "explicacao": "Art. 10, § 1º, do CPP."}, {"id": 2075, "materia": "leg", "nivel": 0, "enunciado": "Ivone é xingada e humilhada pelo marido na frente dos filhos, todos os dias. Pela Lei Maria da Penha, isso é violência:", "opcoes": ["Psicológica", "Patrimonial", "Sexual", "Física"], "explicacao": "Art. 7º, II, da Lei 11.340/2006: conduta que cause dano emocional e diminuição da autoestima."}, {"id": 2090, "materia": "dh", "nivel": 0, "enunciado": "Mesmo sem exercer um direito humano por muitos anos, a pessoa não o perde. Essa característica é a:", "opcoes": ["Imprescritibilidade", "Alienabilidade", "Disponibilidade", "Temporariedade"], "explicacao": "Os direitos humanos não se perdem com o tempo."}, {"id": 2094, "materia": "dh", "nivel": 0, "enunciado": "Liberdade de expressão e direito de votar são direitos de qual dimensão (geração)?", "opcoes": ["Primeira", "Segunda", "Terceira", "Quarta"], "explicacao": "São os direitos civis e políticos, ligados à liberdade."}, {"id": 2095, "materia": "leg", "nivel": 0, "enunciado": "Rafael rasgou os documentos pessoais da companheira para que ela não pudesse sair de casa. Pela Lei Maria da Penha, é violência:", "opcoes": ["Patrimonial", "Moral", "Sexual", "Física"], "explicacao": "Art. 7º, IV: reter, subtrair ou destruir documentos pessoais e bens da mulher."}, {"id": 2096, "materia": "leg", "nivel": 0, "enunciado": "Tiago espalhou mentiras para manchar a honra da ex-companheira. Pela Lei Maria da Penha, é violência:", "opcoes": ["Moral", "Física", "Patrimonial", "Sexual"], "explicacao": "Art. 7º, V: calúnia, difamação ou injúria contra a mulher."}, {"id": 2098, "materia": "leg", "nivel": 0, "enunciado": "Ana namora Bia e é agredida por ela. A Lei Maria da Penha protege Ana?", "opcoes": ["Sim, vale qualquer que seja a orientação sexual", "Não, só vale entre marido e mulher casados no civil", "Não, só vale se morarem juntas", "Só se houver filhos em comum"], "explicacao": "Art. 5º, parágrafo único, da Lei 11.340/2006."}, {"id": 2109, "materia": "pen", "nivel": 0, "enunciado": "Tício, desempregado e sem comida, furtou um pão para alimentar o filho com fome. Pode ser reconhecido o:", "opcoes": ["Estado de necessidade", "Legítima defesa", "Exercício regular de direito", "Estrito cumprimento do dever"], "explicacao": "É o chamado furto famélico (art. 24 do CP)."}, {"id": 2112, "materia": "ppen", "nivel": 0, "enunciado": "Bia processa o vizinho por injúria, crime de ação privada. Ela é chamada de:", "opcoes": ["Querelante", "Ré", "Denunciada", "Promotora"], "explicacao": "Na ação privada, quem acusa é o querelante; o acusado é o querelado."}, {"id": 2114, "materia": "ppen", "nivel": 0, "enunciado": "Depois de iniciar a ação privada, o querelante deixou o processo parado por 30 dias seguidos. Isso causa a:", "opcoes": ["Perempção", "Pronúncia", "Remição", "Citação"], "explicacao": "Art. 60, I, do CPP: a perempção extingue a punibilidade."}, {"id": 2134, "materia": "ppen", "nivel": 0, "enunciado": "Depois da prisão em flagrante, o auto de prisão deve ser enviado ao juiz em até:", "opcoes": ["24 horas", "72 horas", "10 dias", "1 semana"], "explicacao": "Art. 306, § 1º, do CPP."}, {"id": 2137, "materia": "leg", "nivel": 0, "enunciado": "Pela Lei Maria da Penha, a medida protetiva pode ser concedida pelo juiz a pedido:", "opcoes": ["Da ofendida ou do Ministério Público", "Somente do advogado da vítima", "Somente de um parente próximo que more com a vítima", "Somente do agressor"], "explicacao": "Art. 19 da Lei 11.340/2006. O delegado também encaminha o pedido da vítima ao juiz."}, {"id": 2146, "materia": "dh", "nivel": 0, "enunciado": "Saúde, educação e trabalho são direitos de qual dimensão (geração)?", "opcoes": ["Segunda", "Primeira", "Terceira", "Quinta"], "explicacao": "São os direitos sociais, ligados à igualdade."}, {"id": 2147, "materia": "dh", "nivel": 0, "enunciado": "O direito ao meio ambiente equilibrado é de qual dimensão (geração)?", "opcoes": ["Terceira", "Primeira", "Segunda", "Nenhuma"], "explicacao": "Direitos de solidariedade ou fraternidade."}, {"id": 2162, "materia": "ppen", "nivel": 0, "enunciado": "Ao lavrar o flagrante de Rita, o delegado deve informá-la de que ela tem direito de:", "opcoes": ["Ficar calada e ter assistência da família e de advogado", "Escolher a delegacia onde vai ficar presa até o julgamento", "Ser solta assim que pedir", "Recusar a nota de culpa"], "explicacao": "Art. 5º, LXIII, da Constituição."}, {"id": 2164, "materia": "leg", "nivel": 0, "enunciado": "Joana, de 10 anos, sofre maus-tratos em casa. A lei que garante sua proteção integral é o:", "opcoes": ["Estatuto da Criança e do Adolescente", "Estatuto da Pessoa Idosa", "Código de Trânsito Brasileiro", "Estatuto do Desarmamento"], "explicacao": "O ECA (Lei 8.069/1990) adota a doutrina da proteção integral."}, {"id": 2165, "materia": "leg", "nivel": 0, "enunciado": "Ao apreender um adolescente, policiais o colocaram na mesma cela que presos adultos. Pelo ECA, isso é:", "opcoes": ["Proibido", "Permitido por 24 horas", "Permitido se ele estiver calmo", "Obrigatório"], "explicacao": "Art. 175, § 2º, e art. 185 do ECA: o adolescente nunca pode ficar com adultos."}, {"id": 2174, "materia": "dh", "nivel": 0, "enunciado": "Os dois órgãos do sistema interamericano de direitos humanos são:", "opcoes": ["Comissão e Corte Interamericanas", "Conselho de Segurança e Assembleia Geral", "Parlamento e Comissão Europeia", "Corte de Haia e OTAN"], "explicacao": "Previstos na Convenção Americana sobre Direitos Humanos."}, {"id": 2188, "materia": "ppen", "nivel": 0, "enunciado": "Em regra, a necropsia (autópsia) só pode ser feita, no mínimo, depois de quantas horas da morte?", "opcoes": ["6 horas", "1 hora", "24 horas", "72 horas"], "explicacao": "Art. 162 do CPP, salvo se os peritos atestarem antes a evidência da morte."}, {"id": 2200, "materia": "dh", "nivel": 0, "enunciado": "O direito do preso de ser levado, sem demora, à presença de um juiz, previsto no Pacto de San José, deu origem no Brasil à:", "opcoes": ["Audiência de custódia", "Prisão temporária", "Colaboração premiada", "Fiança"], "explicacao": "Art. 7º, item 5, da Convenção Americana."}, {"id": 2201, "materia": "dh", "nivel": 0, "enunciado": "Policiais ameaçaram afogar um suspeito para descobrir onde estava uma vítima. Mesmo com a urgência, isso é:", "opcoes": ["Tortura", "Interrogatório normal", "Exercício do dever", "Permitido em emergência"], "explicacao": "A proibição da tortura é absoluta (Lei 9.455/1997 e Convenção da ONU)."}, {"id": 2275, "materia": "pen", "nivel": 0, "enunciado": "Kauã, de 16 anos, furtou uma bicicleta. Pelo Código Penal, ele:", "opcoes": ["É inimputável e responde pelo ECA", "Responde pelo Código Penal, com pena reduzida", "Vai para o presídio comum", "Paga só uma multa"], "explicacao": "Art. 27 do CP: menores de 18 anos são penalmente inimputáveis."}, {"id": 2279, "materia": "pen", "nivel": 0, "enunciado": "Leo bebeu porque quis e, embriagado, agrediu um colega. A embriaguez voluntária:", "opcoes": ["Não exclui a responsabilidade penal", "Exclui sempre o crime", "Reduz a pena pela metade em qualquer crime", "Leva à absolvição"], "explicacao": "Art. 28, II, do CP."}, {"id": 2285, "materia": "ppen", "nivel": 0, "enunciado": "Na falta de perito oficial, o exame pode ser feito por:", "opcoes": ["Duas pessoas idôneas com curso superior", "Um único policial da equipe que fez a prisão", "O próprio delegado sozinho", "Qualquer vizinho da vítima"], "explicacao": "Art. 159, § 1º, do CPP."}, {"id": 2286, "materia": "ppen", "nivel": 0, "enunciado": "Duas testemunhas contaram versões opostas do mesmo fato. Para confrontá-las frente a frente, faz-se a:", "opcoes": ["Acareação", "Reconstituição", "Pronúncia", "Citação"], "explicacao": "Arts. 229 e 230 do CPP."}, {"id": 2296, "materia": "leg", "nivel": 0, "enunciado": "Um comerciante vendeu cerveja para um garoto de 14 anos. Pelo ECA, isso é:", "opcoes": ["Crime", "Mera advertência", "Fato sem punição", "Só infração de trânsito"], "explicacao": "Art. 243 do ECA, com a redação da Lei 13.106/2015."}, {"id": 2298, "materia": "leg", "nivel": 0, "enunciado": "Seu Antônio tem 82 anos. Pelo Estatuto da Pessoa Idosa, ele tem prioridade especial, que vale para quem tem mais de:", "opcoes": ["80 anos", "60 anos", "65 anos", "70 anos"], "explicacao": "Art. 3º, § 2º, da Lei 10.741/2003: os maiores de 80 anos têm prioridade sobre os demais idosos."}, {"id": 2300, "materia": "leg", "nivel": 0, "enunciado": "Um filho deixou a mãe idosa sozinha, sem comida e sem cuidados básicos. Pelo Estatuto da Pessoa Idosa, isso pode ser:", "opcoes": ["Crime", "Só falta de educação", "Infração de trânsito", "Conduta permitida"], "explicacao": "Arts. 98 e 99 da Lei 10.741/2003 punem o abandono e a exposição da pessoa idosa a perigo."}, {"id": 2301, "materia": "leg", "nivel": 0, "enunciado": "Lia herdou do pai uma espingarda de uso permitido e quer mantê-la em casa legalmente. Ela precisa:", "opcoes": ["Registrar a arma", "Guardar só a nota fiscal", "Avisar os vizinhos", "Pedir licença ao prefeito"], "explicacao": "Art. 3º da Lei 10.826/2003: é obrigatório o registro de arma de fogo."}, {"id": 2302, "materia": "leg", "nivel": 0, "enunciado": "Para andar com uma arma na cintura pela rua, além do registro, é preciso ter:", "opcoes": ["Porte de arma", "Nota fiscal", "Carteira de motorista", "Título de eleitor"], "explicacao": "O porte é a autorização para portar a arma fora de casa (arts. 6º e 10 da Lei 10.826/2003)."}, {"id": 2345, "materia": "dh", "nivel": 0, "enunciado": "Um soldado diz que torturou um preso porque recebeu ordem do chefe. Isso justifica a tortura?", "opcoes": ["Não, nunca", "Sim, sempre", "Só em guerra", "Só se a ordem for escrita"], "explicacao": "A ordem de superior não pode ser invocada para justificar a tortura (art. 2º, item 3, da Convenção)."}, {"id": 2346, "materia": "dh", "nivel": 0, "enunciado": "Pelo princípio da não devolução, um refugiado:", "opcoes": ["Não pode ser mandado a país onde corre risco", "Deve voltar ao seu país em até 30 dias após chegar", "Perde todos os direitos no Brasil", "Só pode ficar se tiver emprego"], "explicacao": "Princípio do non-refoulement (art. 33 da Convenção de 1951 e Lei 9.474/1997)."}, {"id": 2347, "materia": "dh", "nivel": 0, "enunciado": "Uma família fugiu de perseguição política no seu país e chegou ao Brasil pedindo proteção. Ela pode pedir:", "opcoes": ["Refúgio", "Extradição", "Deportação", "Expulsão"], "explicacao": "Lei 9.474/1997: refúgio para quem sofre perseguição por raça, religião, nacionalidade, grupo social ou opinião política."}, {"id": 2349, "materia": "dh", "nivel": 0, "enunciado": "Além do sistema global da ONU, o Brasil faz parte do sistema regional de direitos humanos da:", "opcoes": ["OEA", "OTAN", "União Africana", "União Europeia"], "explicacao": "É o sistema interamericano: Comissão e Corte Interamericana."}, {"id": 2353, "materia": "dh", "nivel": 0, "enunciado": "Lúcio foi preso e não tem dinheiro para advogado. Quem presta assistência jurídica gratuita a ele é a:", "opcoes": ["Defensoria Pública", "Polícia Civil", "Receita Federal", "Câmara de Vereadores"], "explicacao": "Art. 134 da Constituição."}, {"id": 2659, "materia": "pen", "nivel": 0, "enunciado": "Logo após ser provocado injustamente, Zeca matou o provocador sob o domínio de violenta emoção. É homicídio:", "opcoes": ["Privilegiado", "Qualificado", "Culposo", "Hediondo"], "explicacao": "Art. 121, § 1º, do CP: a pena pode ser reduzida de 1/6 a 1/3."}, {"id": 2677, "materia": "leg", "nivel": 0, "enunciado": "Pela Lei 11.343/2006, entregar droga a outra pessoa, ainda que de graça, pode configurar:", "opcoes": ["Tráfico de drogas", "Uso pessoal", "Contravenção penal", "Conduta permitida"], "explicacao": "O art. 33 pune \"fornecer drogas, ainda que gratuitamente\"."}, {"id": 2682, "materia": "leg", "nivel": 0, "enunciado": "Nino cultivava alguns pés de maconha no quintal só para fumar. Pela Lei de Drogas, ele está sujeito às penas do:", "opcoes": ["Usuário (art. 28)", "Tráfico (art. 33)", "Código Civil", "Estatuto da Criança"], "explicacao": "Art. 28, § 1º, da Lei 11.343/2006: o cultivo para consumo pessoal tem as mesmas medidas do usuário."}, {"id": 2684, "materia": "leg", "nivel": 0, "enunciado": "Cauã, sem carteira de motorista, dirigia em zigue-zague perto de uma escola, gerando perigo. Pelo CTB, ele comete:", "opcoes": ["Crime", "Só uma infração leve", "Nada, se não bater", "Contravenção penal"], "explicacao": "Art. 309 do CTB: dirigir sem habilitação, gerando perigo de dano."}, {"id": 2732, "materia": "dh", "nivel": 0, "enunciado": "Para denunciar violações de direitos humanos, como agressões a idosos ou crianças, o número nacional é o:", "opcoes": ["Disque 100", "Disque 190", "Disque 192", "Disque 193"], "explicacao": "O Disque 100 é o Disque Direitos Humanos."}, {"id": 2735, "materia": "dh", "nivel": 0, "enunciado": "Para denunciar violência contra a mulher, a central nacional de atendimento é o:", "opcoes": ["Ligue 180", "Ligue 100", "Ligue 199", "Ligue 192"], "explicacao": "Central de Atendimento à Mulher."}, {"id": 5666, "materia": "ppen", "nivel": 0, "enunciado": "No reconhecimento de pessoa, quem vai reconhecer deve, primeiro:", "opcoes": ["Descrever a pessoa a ser reconhecida", "Ver só a foto do suspeito", "Conversar a sós com o suspeito", "Ouvir a opinião do delegado"], "explicacao": "Art. 226, I, do CPP."}, {"id": 5678, "materia": "leg", "nivel": 0, "enunciado": "Dois motoristas apostaram corrida numa avenida de Salvador. Pelo CTB, participar de racha é:", "opcoes": ["Crime", "Permitido de madrugada", "Infração leve", "Contravenção"], "explicacao": "Art. 308 do CTB."}, {"id": 5776, "materia": "leg", "nivel": 0, "enunciado": "Depois de bater o carro, Hélio fugiu do local para não ser identificado. Pelo CTB, isso é:", "opcoes": ["Crime", "Só uma infração média", "Um direito do motorista", "Conduta sem punição"], "explicacao": "Art. 305 do CTB: afastar-se do local do sinistro para fugir da responsabilidade."}, {"id": 5833, "materia": "dh", "nivel": 0, "enunciado": "A Lei de Migração (Lei 13.445/2017) tem como princípio o:", "opcoes": ["Repúdio à xenofobia e ao racismo", "Fechamento total das fronteiras", "Fim do direito de asilo", "Trabalho forçado do migrante"], "explicacao": "Art. 3º, II, da Lei 13.445/2017."}, {"id": 6006, "materia": "dh", "nivel": 0, "enunciado": "Na fila do banco, Dona Célia, de 70 anos, foi humilhada por causa da idade. Isso pode ser crime previsto no:", "opcoes": ["Estatuto da Pessoa Idosa", "Código de Defesa do Consumidor", "Estatuto da Criança", "Código de Trânsito"], "explicacao": "Art. 96, § 1º, da Lei 10.741/2003."}, {"id": 6095, "materia": "ml", "nivel": 0, "enunciado": "A técnica que identifica pessoas pelas impressões digitais é a:", "opcoes": ["Papiloscopia", "Toxicologia", "Balística", "Tanatologia"], "explicacao": "A papiloscopia estuda as papilas dérmicas (digitais)."}, {"id": 6106, "materia": "leg", "nivel": 0, "enunciado": "A Lei de Tortura é a Lei:", "opcoes": ["9.455/1997", "8.072/1990", "13.869/2019", "9.099/1995"], "explicacao": "8.072 trata dos crimes hediondos, 13.869 do abuso de autoridade e 9.099 dos Juizados Especiais."}, {"id": 6454, "materia": "pen", "nivel": 0, "enunciado": "Por mensagem, Caio prometeu \"acabar com a vida\" do colega se ele contasse um segredo. O crime é:", "opcoes": ["Ameaça", "Calúnia", "Difamação", "Injúria"], "explicacao": "Art. 147 do CP: ameaçar alguém de causar mal injusto e grave."}, {"id": 6470, "materia": "leg", "nivel": 0, "enunciado": "Um agente penitenciário submeteu um preso a sofrimento físico como castigo, sem nenhuma previsão legal. Isso é:", "opcoes": ["Tortura", "Disciplina normal", "Exercício regular de direito", "Lesão leve"], "explicacao": "Art. 1º, § 1º, da Lei 9.455/1997."}, {"id": 6506, "materia": "dh", "nivel": 0, "enunciado": "A Lei Maria da Penha foi criada depois que o Brasil foi responsabilizado, no caso de Maria da Penha, pela:", "opcoes": ["Comissão Interamericana de Direitos Humanos", "Organização Mundial da Saúde, em Genebra, na Suíça", "Corte Internacional de Haia", "Assembleia Geral da ONU"], "explicacao": "Em 2001, a Comissão Interamericana responsabilizou o Brasil por omissão."}, {"id": 6533, "materia": "ml", "nivel": 0, "enunciado": "Um corpo carbonizado foi identificado pelos dentes. Isso é trabalho da:", "opcoes": ["Odontologia legal", "Balística forense", "Psiquiatria forense", "Toxicologia"], "explicacao": "A arcada dentária é muito resistente e serve para identificação."}, {"id": 6539, "materia": "pen", "nivel": 0, "enunciado": "Mesmo depois de mandado embora, Juca continuou dentro da casa do vizinho. O crime é:", "opcoes": ["Violação de domicílio", "Furto", "Dano", "Esbulho"], "explicacao": "Art. 150 do CP: entrar ou permanecer em casa alheia contra a vontade do morador."}, {"id": 6602, "materia": "dh", "nivel": 0, "enunciado": "Ana foi algemada sem resistir nem tentar fugir, e o policial não justificou por escrito. Pela Súmula Vinculante 11, isso pode gerar:", "opcoes": ["Nulidade da prisão e responsabilidade do agente", "Aumento da pena da presa por desobediência à polícia", "Prisão preventiva automática", "Nenhuma consequência"], "explicacao": "A súmula prevê responsabilidade disciplinar, civil e penal do agente e nulidade da prisão ou do ato."}, {"id": 6629, "materia": "ml", "nivel": 0, "enunciado": "O exame que detecta álcool ou drogas no sangue de um motorista é da:", "opcoes": ["Toxicologia forense", "Papiloscopia", "Balística", "Odontologia legal"], "explicacao": "A toxicologia estuda substâncias tóxicas no organismo."}, {"id": 6652, "materia": "ppen", "nivel": 0, "enunciado": "Uma testemunha mentiu de propósito em juízo. Ela comete:", "opcoes": ["Falso testemunho", "Calúnia", "Fraude processual", "Nenhum crime"], "explicacao": "Art. 342 do Código Penal."}, {"id": 6703, "materia": "dh", "nivel": 0, "enunciado": "Pela Súmula Vinculante 11, quando a polícia usa algemas, a excepcionalidade deve ser:", "opcoes": ["Justificada por escrito", "Autorizada pelo juiz antes", "Comunicada à imprensa", "Filmada pelo próprio preso"], "explicacao": "Sob pena de responsabilidade e de nulidade da prisão ou do ato."}, {"id": 6704, "materia": "dh", "nivel": 0, "enunciado": "O ECA adota a doutrina da:", "opcoes": ["Proteção integral", "Situação irregular", "Punição severa", "Tutela penal"], "explicacao": "Crianças e adolescentes são sujeitos de direitos (art. 1º do ECA)."}, {"id": 7339, "materia": "pen", "nivel": 0, "enunciado": "Com violência, Edu obrigou o vizinho a apagar uma postagem que a lei não mandava apagar. O crime é:", "opcoes": ["Constrangimento ilegal", "Ameaça", "Furto", "Dano"], "explicacao": "Art. 146 do CP."}, {"id": 7341, "materia": "pen", "nivel": 0, "enunciado": "Gil exigiu dinheiro de Lia para não divulgar fotos íntimas dela. O crime é:", "opcoes": ["Extorsão", "Furto", "Apropriação indébita", "Dano"], "explicacao": "Art. 158 do CP: constranger alguém, com grave ameaça, para obter vantagem econômica."}, {"id": 7346, "materia": "pen", "nivel": 0, "enunciado": "Ao ver uma pessoa ferida na estrada, Davi seguiu viagem, embora pudesse ajudar sem risco. Ele cometeu:", "opcoes": ["Omissão de socorro", "Lesão corporal", "Homicídio culposo", "Nenhum crime"], "explicacao": "Art. 135 do CP."}, {"id": 7378, "materia": "ppen", "nivel": 0, "enunciado": "Chamada para depor contra o próprio marido, Rosa pode se recusar porque:", "opcoes": ["O cônjuge pode recusar-se a depor", "Ninguém é obrigado a depor", "Ela é a vítima do crime", "Mulheres não depõem"], "explicacao": "Art. 206 do CPP: também ascendente, descendente e irmão, salvo se não houver outra prova."}, {"id": 7379, "materia": "ppen", "nivel": 0, "enunciado": "Um médico sabe de um fato por segredo profissional. Sobre esse fato, ele:", "opcoes": ["Não deve depor, salvo se liberado e quiser", "É obrigado a contar tudo", "Deve depor só por escrito", "Pode ser preso por desobediência se ficar calado"], "explicacao": "Art. 207 do CPP."}, {"id": 7381, "materia": "ppen", "nivel": 0, "enunciado": "No interrogatório, Júlio ficou em silêncio. Isso:", "opcoes": ["Não pode prejudicar a defesa dele", "Vale como confissão", "Aumenta a pena", "Gera prisão imediata"], "explicacao": "Art. 186, parágrafo único, do CPP."}, {"id": 7382, "materia": "ppen", "nivel": 0, "enunciado": "O interrogatório do acusado em juízo deve ser feito na presença do:", "opcoes": ["Defensor", "Repórter", "Prefeito", "Vizinho"], "explicacao": "Art. 185 do CPP."}, {"id": 7410, "materia": "leg", "nivel": 0, "enunciado": "Bruno sequestrou um empresário e exigiu resgate da família. A extorsão mediante sequestro é crime:", "opcoes": ["Hediondo", "De menor potencial ofensivo", "Culposo", "De ação privada"], "explicacao": "Art. 159 do CP e art. 1º, IV, da Lei 8.072/1990."}, {"id": 7411, "materia": "leg", "nivel": 0, "enunciado": "Preso por latrocínio, crime hediondo, Duda pediu para pagar fiança. Isso é possível?", "opcoes": ["Não, crime hediondo é inafiançável", "Sim, se ele for primário e tiver bons antecedentes", "Sim, em qualquer caso", "Sim, se o juiz quiser"], "explicacao": "Art. 2º, II, da Lei 8.072/1990 e art. 5º, XLIII, da Constituição."}, {"id": 7413, "materia": "leg", "nivel": 0, "enunciado": "Gil cometeu um crime com pena máxima de 1 ano. Em regra, ele será julgado:", "opcoes": ["No Juizado Especial Criminal", "No Tribunal do Júri", "No Supremo Tribunal Federal", "Na Justiça Militar"], "explicacao": "Infração de menor potencial ofensivo: pena máxima de até 2 anos (art. 61 da Lei 9.099/1995)."}, {"id": 7417, "materia": "leg", "nivel": 0, "enunciado": "No Juizado Especial Criminal, o acordo em que o MP propõe pena alternativa imediata, sem processo, é a:", "opcoes": ["Transação penal", "Colaboração premiada", "Pronúncia", "Delação"], "explicacao": "Art. 76 da Lei 9.099/1995."}, {"id": 7419, "materia": "leg", "nivel": 0, "enunciado": "A Lei de Abuso de Autoridade em vigor é a Lei:", "opcoes": ["13.869/2019", "4.898/1965", "9.455/1997", "12.850/2013"], "explicacao": "A Lei 13.869/2019 revogou a antiga Lei 4.898/1965."}, {"id": 7565, "materia": "ml", "nivel": 0, "enunciado": "Uma queimadura causada por fogo é produzida por energia de ordem:", "opcoes": ["Física", "Química", "Biológica", "Bioquímica"], "explicacao": "O calor é energia física (térmica)."}, {"id": 7591, "materia": "ppen", "nivel": 0, "enunciado": "A prisão preventiva de um suspeito é decretada pelo:", "opcoes": ["Juiz", "Delegado", "Escrivão", "Investigador"], "explicacao": "Art. 311 do CPP, a pedido do MP ou por representação do delegado."}, {"id": 7619, "materia": "dh", "nivel": 0, "enunciado": "Joel foi acusado de um furto pelos vizinhos. Pela Declaração Universal, até que a culpa seja provada em julgamento com defesa, ele é:", "opcoes": ["Presumido inocente", "Considerado culpado", "Obrigado a provar a inocência", "Preso automaticamente"], "explicacao": "Art. 11 da Declaração Universal dos Direitos Humanos."}, {"id": 7682, "materia": "leg", "nivel": 0, "enunciado": "Por curiosidade, um agente entrou numa casa sem mandado e sem nenhuma situação de flagrante. Ele pode responder por:", "opcoes": ["Abuso de autoridade", "Nada", "Exercício regular de direito", "Estrito cumprimento do dever"], "explicacao": "Art. 22 da Lei 13.869/2019."}, {"id": 7684, "materia": "leg", "nivel": 0, "enunciado": "Um restaurante impediu Marcos de entrar por causa da cor da pele dele. Isso é:", "opcoes": ["Crime de racismo", "Injúria simples", "Infração administrativa", "Contravenção"], "explicacao": "Art. 8º da Lei 7.716/1989."}, {"id": 7686, "materia": "leg", "nivel": 0, "enunciado": "Pela Lei de Execução Penal, o preso que trabalha diminui a pena em 1 dia a cada:", "opcoes": ["3 dias de trabalho", "10 dias de trabalho", "30 dias de trabalho", "7 dias de trabalho"], "explicacao": "Remição pelo trabalho (art. 126, § 1º, II, da LEP)."}, {"id": 7687, "materia": "leg", "nivel": 0, "enunciado": "Pela Lei de Execução Penal, o preso que estuda diminui 1 dia de pena a cada:", "opcoes": ["12 horas de estudo", "2 horas de estudo", "100 horas de estudo", "1 hora de estudo"], "explicacao": "Art. 126, § 1º, I, da LEP: 12 horas divididas em, no mínimo, 3 dias."}, {"id": 7688, "materia": "leg", "nivel": 0, "enunciado": "Para infiltrar um policial numa organização criminosa, pela Lei 12.850/2013, é preciso:", "opcoes": ["Autorização judicial", "Só a ordem do delegado", "Só a vontade do policial", "Autorização do prefeito"], "explicacao": "Art. 10 da Lei 12.850/2013."}, {"id": 7721, "materia": "ppen", "nivel": 0, "enunciado": "A citação do réu serve para:", "opcoes": ["Avisá-lo do processo para que se defenda", "Mandá-lo direto para a prisão até o julgamento final", "Chamar testemunhas da vítima", "Arquivar o processo"], "explicacao": "Arts. 351 e seguintes do CPP."}, {"id": 7878, "materia": "ml", "nivel": 0, "enunciado": "Um soco no rosto, sem cortar a pele, causa lesão por instrumento:", "opcoes": ["Contundente", "Cortante", "Perfurante", "Perfurocortante"], "explicacao": "O instrumento contundente age por pressão ou choque."}, {"id": 7890, "materia": "dh", "nivel": 0, "enunciado": "A igualdade perante a lei significa que todas as pessoas devem ser tratadas:", "opcoes": ["Sem discriminação", "Conforme sua renda", "Conforme sua religião", "Conforme sua profissão"], "explicacao": "Art. 5º, caput, da Constituição e art. 7º da Declaração Universal."}, {"id": 7922, "materia": "leg", "nivel": 0, "enunciado": "Um traficante abriu uma lanchonete de fachada para fingir que seu dinheiro vinha das vendas. Isso é:", "opcoes": ["Lavagem de dinheiro", "Estelionato", "Receptação", "Contrabando"], "explicacao": "Ocultar ou dissimular a origem de bens vindos de infração penal (art. 1º da Lei 9.613/1998)."}, {"id": 7927, "materia": "ppen", "nivel": 0, "enunciado": "Se o réu não for encontrado para receber a citação, ela é feita por:", "opcoes": ["Edital", "Mensagem para o vizinho", "Anúncio de rádio", "Carta ao empregador"], "explicacao": "Art. 361 do CPP."}, {"id": 7928, "materia": "ppen", "nivel": 0, "enunciado": "Rui matou a ex-mulher de propósito. Ele será julgado pelo:", "opcoes": ["Tribunal do Júri", "Juizado Especial Criminal", "Supremo Tribunal Federal", "Juiz de paz"], "explicacao": "Crimes dolosos contra a vida vão a júri (art. 5º, XXXVIII, da Constituição)."}, {"id": 7929, "materia": "ppen", "nivel": 0, "enunciado": "No Tribunal do Júri, os jurados votam as perguntas sobre o crime de forma:", "opcoes": ["Sigilosa", "Aberta, em voz alta", "Pela internet", "Por telefone"], "explicacao": "Arts. 485 a 487 do CPP: votação na sala especial, com cédulas, garantindo o sigilo."}, {"id": 9962, "materia": "dh", "nivel": 0, "enunciado": "Numa fazenda, trabalhadores cumpriam jornada exaustiva, em condições degradantes. Isso é:", "opcoes": ["Redução a condição análoga à de escravo", "Hora extra normal, paga conforme a convenção coletiva", "Contrato de experiência", "Trabalho voluntário"], "explicacao": "Art. 149 do Código Penal."}, {"id": 9964, "materia": "dh", "nivel": 0, "enunciado": "Recrutar uma pessoa com engano para explorá-la sexualmente ou remover seus órgãos é:", "opcoes": ["Tráfico de pessoas", "Intercâmbio", "Trabalho temporário", "Turismo"], "explicacao": "Art. 149-A do Código Penal."}, {"id": 9971, "materia": "leg", "nivel": 0, "enunciado": "Uma escola recusou a matrícula de Dudu por ele ser cadeirante. Pela lei, a escola:", "opcoes": ["Cometeu crime", "Agiu corretamente", "Só faltou com a ética", "Pode cobrar mais caro"], "explicacao": "Art. 8º, I, da Lei 7.853/1989, com a redação da Lei 13.146/2015."}, {"id": 9975, "materia": "leg", "nivel": 0, "enunciado": "O tráfico privilegiado, a associação para o tráfico e o financiamento do tráfico estão na Lei:", "opcoes": ["11.343/2006", "9.613/1998", "8.072/1990", "10.826/2003"], "explicacao": "Arts. 33, § 4º, 35 e 36 da Lei de Drogas."}, {"id": 9986, "materia": "ml", "nivel": 0, "enunciado": "O documento médico que informa a morte e sua causa é a:", "opcoes": ["Declaração de óbito", "Certidão de nascimento", "Carteira de vacinação", "Nota fiscal"], "explicacao": "A partir dela o cartório emite a certidão de óbito."}, {"id": 10015, "materia": "ppen", "nivel": 0, "enunciado": "Joca está preso ilegalmente, e a irmã dele, que não é advogada, quer ajudar. Ela pode:", "opcoes": ["Pedir habeas corpus em favor dele", "Apenas esperar o fim do processo para recorrer", "Somente reclamar no jornal", "Nada, sem advogado"], "explicacao": "Art. 654 do CPP: qualquer pessoa pode impetrar habeas corpus."}, {"id": 10017, "materia": "ppen", "nivel": 0, "enunciado": "Descoberta uma prova ilícita no processo, ela deve ser:", "opcoes": ["Retirada do processo", "Usada normalmente", "Lida para os jurados", "Guardada como prova"], "explicacao": "Art. 157 do CPP: desentranhamento."}, {"id": 10022, "materia": "ppen", "nivel": 0, "enunciado": "Depois que o juiz recebeu a denúncia contra Edu, ele passou a ser chamado de:", "opcoes": ["Réu", "Querelante", "Assistente", "Perito"], "explicacao": "Antes disso, na investigação, ele é investigado ou indiciado."}, {"id": 10456, "materia": "dh", "nivel": 0, "enunciado": "Pela Constituição, nenhum brasileiro pode ser condenado a pena de:", "opcoes": ["Trabalho forçado", "Multa", "Prestação de serviços", "Perda de bens"], "explicacao": "Art. 5º, XLVII: são proibidas penas de trabalhos forçados, banimento, cruéis, perpétuas e de morte (salvo guerra)."}]$q$::jsonb)
  as x(id integer, materia text, nivel smallint, enunciado text, opcoes jsonb, explicacao text)
on conflict (id) do update set materia = excluded.materia, nivel = excluded.nivel, enunciado = excluded.enunciado, opcoes = excluded.opcoes, explicacao = excluded.explicacao;

select materia, count(*) as trocadas from public.questoes where id in (2020,2030,2031,2043,2053,2071,2074,2075,2090,2094,2095,2096,2098,2109,2112,2114,2134,2137,2146,2147,2162,2164,2165,2174,2188,2200,2201,2275,2279,2285,2286,2296,2298,2300,2301,2302,2345,2346,2347,2349,2353,2659,2677,2682,2684,2732,2735,5666,5678,5776,5833,6006,6095,6106,6454,6470,6506,6533,6539,6602,6629,6652,6703,6704,7339,7341,7346,7378,7379,7381,7382,7410,7411,7413,7417,7419,7565,7591,7619,7682,7684,7686,7687,7688,7721,7878,7890,7922,7927,7928,7929,9962,9964,9971,9975,9986,10015,10017,10022,10456) group by materia order by 2 desc;
select public.questoes_versao() as nova_versao;
